using Microsoft.Playwright;
namespace InsuranceAutomation.Core;
public sealed class UiActions { readonly BrowserSession _b; readonly LocatorRepository _l; public UiActions(BrowserSession b,LocatorRepository l){_b=b;_l=l;} ILocator L(string id)=>_l.Get(_b.Page,id); public async Task ClickAsync(string id)=>await L(id).ClickAsync(); public async Task FillAsync(string id,string value){var l=L(id);await l.ClickAsync();await l.FillAsync("");await l.PressSequentiallyAsync(value);} public async Task SmartSetAsync(string id,string value){var l=L(id);var type=await l.GetAttributeAsync("type");if(type is "checkbox" or "radio"){if(value.Equals("false",StringComparison.OrdinalIgnoreCase)||value.Equals("no",StringComparison.OrdinalIgnoreCase))await l.UncheckAsync();else await l.CheckAsync();return;}var tag=await l.EvaluateAsync<string>("e=>e.tagName.toLowerCase()");if(tag=="select"){await l.SelectOptionAsync(new SelectOptionValue{Label=value});return;}await FillAsync(id,value);} public async Task SelectAsync(string id,string value){var l=L(id);try{await l.SelectOptionAsync(new SelectOptionValue{Label=value});}catch{await l.ClickAsync();await _b.Page.GetByRole(AriaRole.Option,new(){Name=value,Exact=true}).ClickAsync();}} public async Task PressAsync(string id,string key)=>await L(id).PressAsync(key); public async Task<bool> ExistsAsync(string id)=>await L(id).CountAsync()>0; public async Task WaitAsync(string id,string expected){var l=L(id); if(expected.Contains("not",StringComparison.OrdinalIgnoreCase)||expected.Contains("No longer",StringComparison.OrdinalIgnoreCase))await l.WaitForAsync(new(){State=WaitForSelectorState.Detached});else await l.WaitForAsync(new(){State=WaitForSelectorState.Visible});} public async Task VerifyAsync(string id,string expected,string property){var l=L(id);if(expected.Equals("Visible",StringComparison.OrdinalIgnoreCase)||expected.Equals("Exists",StringComparison.OrdinalIgnoreCase)||expected.Equals("True",StringComparison.OrdinalIgnoreCase)){if(await l.CountAsync()==0)throw new InvalidOperationException($"Expected locator {id} to exist.");await l.WaitForAsync(new(){State=WaitForSelectorState.Visible});return;}var actual=await CaptureAsync(id,property);if(!string.Equals(actual,expected,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException($"Expected '{expected}' but found '{actual}'.");} public async Task<string> CaptureAsync(string id,string property=""){var l=L(id);if(property.Contains("Value",StringComparison.OrdinalIgnoreCase)){try{return await l.InputValueAsync();}catch{}}return (await l.InnerTextAsync()).Trim();} }
